import { BookmarkIcon, ChevronDownIcon, UsersIcon } from 'lucide-react';
import { useState } from 'react';
import type { FilterState } from '@/components/company-os/filter-chips';
import { SaveViewDialog } from '@/components/company-os/save-view-dialog';
import type { SaveViewLabels } from '@/components/company-os/save-view-dialog';
import { activeView } from '@/components/company-os/saved-view-query';
import type { SavedViewItem } from '@/components/company-os/saved-view-query';
import { Button } from '@/components/ui/button';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { navigateWithQuery } from '@/lib/navigation';
import { cn } from '@/lib/utils';

export type SavedViewsLabels = {
    views: string;
    savedViews: string;
    empty: string;
    saveCurrent: string;
    update: (name: string) => string;
    remove: (name: string) => string;
    sharedBy: (owner: string) => string;
};

export const savedViewsLabels: SavedViewsLabels = {
    views: 'Views',
    savedViews: 'Saved views',
    empty: 'Set filters, layout and grouping, then save them here to come back in one click.',
    saveCurrent: 'Save current view',
    update: (name) => `Update “${name}”`,
    remove: (name) => `Delete “${name}”`,
    sharedBy: (owner) => `Shared by ${owner}`,
};

export function SavedViewsMenu({
    state,
    views,
    canShare,
    implied = [],
    saving,
    saveError,
    onSave,
    onUpdate,
    onDelete,
    labels = savedViewsLabels,
    dialogLabels,
}: {
    state: FilterState;
    views: SavedViewItem[];
    canShare: boolean;
    implied?: string[];
    saving: boolean;
    saveError?: string;
    onSave: (data: { name: string; shared: boolean }) => void;
    onUpdate: (view: SavedViewItem) => void;
    onDelete: (view: SavedViewItem) => void;
    labels?: SavedViewsLabels;
    dialogLabels?: SaveViewLabels;
}) {
    const [open, setOpen] = useState(false);
    const active = activeView(state, views, implied);

    return (
        <>
            <DropdownMenu>
                <DropdownMenuTrigger asChild>
                    <Button variant="outline" className={cn('max-w-48', active && 'text-primary')}>
                        <BookmarkIcon />
                        <span className="truncate">{active?.name ?? labels.views}</span>
                        <ChevronDownIcon className="text-slate-400" />
                    </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-64">
                    <DropdownMenuLabel className="font-light">{labels.savedViews}</DropdownMenuLabel>
                    {views.length === 0 && <p className="px-2 pb-2 text-sm text-muted-foreground">{labels.empty}</p>}
                    {views.map((view) => (
                        <DropdownMenuItem
                            key={view.id}
                            className={cn(view.id === active?.id && 'bg-primary/10 text-primary')}
                            onSelect={() => navigateWithQuery(state.url, view.query, { preserveScroll: true })}
                        >
                            <span className="truncate">{view.name}</span>
                            {view.is_shared && <UsersIcon className="ml-auto size-3.5" aria-label={labels.sharedBy(view.owner)} />}
                        </DropdownMenuItem>
                    ))}
                    <DropdownMenuSeparator />
                    <DropdownMenuItem onSelect={() => setOpen(true)}>{labels.saveCurrent}</DropdownMenuItem>
                    {active?.can_update && <DropdownMenuItem onSelect={() => onUpdate(active)}>{labels.update(active.name)}</DropdownMenuItem>}
                    {active?.can_delete && (
                        <DropdownMenuItem variant="destructive" onSelect={() => onDelete(active)}>
                            {labels.remove(active.name)}
                        </DropdownMenuItem>
                    )}
                </DropdownMenuContent>
            </DropdownMenu>
            <SaveViewDialog open={open} onOpenChange={setOpen} canShare={canShare} processing={saving} error={saveError} onSave={onSave} labels={dialogLabels} />
        </>
    );
}

import { useState } from 'react';
import type { FormEvent } from 'react';
import { InputError } from '@/components/company-os/field-row';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

export type SaveViewLabels = { title: string; name: string; namePlaceholder: string; share: string; cancel: string; save: string };

export const saveViewLabels: SaveViewLabels = {
    title: 'Save view',
    name: 'Name',
    namePlaceholder: 'Overdue bugs',
    share: 'Share with everyone who can see this list',
    cancel: 'Cancel',
    save: 'Save view',
};

export function SaveViewDialog({
    open,
    onOpenChange,
    canShare,
    processing,
    error,
    onSave,
    labels = saveViewLabels,
}: {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    canShare: boolean;
    processing: boolean;
    error?: string;
    onSave: (data: { name: string; shared: boolean }) => void;
    labels?: SaveViewLabels;
}) {
    const [name, setName] = useState('');
    const [shared, setShared] = useState(false);

    const submit = (event: FormEvent) => {
        event.preventDefault();
        onSave({ name: name.trim(), shared });
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-md">
                <form onSubmit={submit} className="grid gap-6">
                    <DialogHeader>
                        <DialogTitle>{labels.title}</DialogTitle>
                    </DialogHeader>
                    <div className="grid gap-2">
                        <Label htmlFor="view-name" className="font-light">
                            {labels.name}
                        </Label>
                        <Input
                            id="view-name"
                            autoFocus
                            value={name}
                            onChange={(event) => setName(event.target.value)}
                            placeholder={labels.namePlaceholder}
                            aria-invalid={Boolean(error)}
                        />
                        <InputError message={error} />
                    </div>
                    {canShare && (
                        <Label className="flex items-center gap-2 font-light">
                            <Checkbox checked={shared} onCheckedChange={(checked) => setShared(checked === true)} />
                            {labels.share}
                        </Label>
                    )}
                    <DialogFooter>
                        <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
                            {labels.cancel}
                        </Button>
                        <Button type="submit" disabled={processing || name.trim() === ''}>
                            {labels.save}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
}

import type { FilterState } from '@/components/company-os/filter-chips';

export type SavedViewItem = {
    id: string;
    name: string;
    query: Record<string, string>;
    is_shared: boolean;
    owner: string;
    can_update: boolean;
    can_delete: boolean;
};

const viewKeys = ['view', 'group', 'sort', 'page'];

export function viewDefinition(state: FilterState) {
    const { view, group, sort } = state.filters;
    const filters = Object.fromEntries(
        Object.entries(state.filters).filter(([key, value]) => !viewKeys.includes(key) && value !== ''),
    );

    return {
        layout: view ?? 'list',
        group_by: group || null,
        sort: sort || null,
        filters,
    };
}

function comparable(query: Record<string, string>, ignored: string[]) {
    return JSON.stringify(
        Object.entries(query)
            .filter(([key, value]) => value !== '' && key !== 'page' && !ignored.includes(key))
            .sort(([a], [b]) => a.localeCompare(b)),
    );
}

export function activeView(state: FilterState, views: SavedViewItem[], implied: string[] = []): SavedViewItem | undefined {
    const current = comparable(state.filters, implied);

    return views.find((view) => comparable(view.query, implied) === current);
}
